/* 识字 Zeichentrainer — the app's own texts in other languages (v253, H: "Multi language UI and translations").
   English is the key: t("Save card") looks the sentence up in the current language and falls back to the English text
   itself, so a missing translation shows English, never a key. {0}, {1} … are filled in by t(); a count word ("card",
   "cards") may carry the number as {0} where the language puts it elsewhere ("カード{0}枚"). The learning content stays
   Chinese, pinyin and the meaning; the owner's tools (Diagnostics, All users, Feedback, the usage report) stay English.
   To add a language: one more entry in LANGS, LANG_LOCALE and LANG_NAME, and one more column below — plus an entry in
   PLURAL when its count words have more than the two forms English has (v401, Russian). Vietnamese, Thai and Indonesian
   (v402, H: "Ebenso Vietnamesisch, Thai, Indonesisch") inflect for no number at all, so both members of every count word
   carry the same string, as Japanese and Korean do, and none of the three needs a PLURAL rule. */
const LANGS=[["en","English"],["de","Deutsch"],["fr","Français"],["es","Español"],["ja","日本語"],["ko","한국어"],["ru","Русский"],["vi","Tiếng Việt"],["th","ไทย"],["id","Bahasa Indonesia"]];
const LANG_LOCALE={en:"en-GB",de:"de-DE",fr:"fr-FR",es:"es-ES",ja:"ja-JP",ko:"ko-KR",ru:"ru-RU",vi:"vi-VN",th:"th-TH",id:"id-ID"}; /* th-TH writes the year in the Buddhist era (2569), which is what a Thai phone shows everywhere else (v402) */
const LANG_NAME={en:"English",de:"German",fr:"French",es:"Spanish",ja:"Japanese",ko:"Korean",ru:"Russian",vi:"Vietnamese",th:"Thai",id:"Indonesian"}; /* the languages' English names, for the AI's prompt (v256) — a language missing here would get an English meaning from the model, so this list moves with LANGS */
let LANG="en";
function langDefault(){ let l=String(navigator.language||"").toLowerCase().slice(0,2); if(l==="in") l="id"; /* Android's locale layer still hands out the legacy code "in" for Indonesian and Chromium passes it through, so the phone would have opened in English (v402) */
  return LANGS.some(([c])=>c===l)?l:"en"; }
function t(key,...args){ const d=L10N[LANG]; let s=d&&d[key]!=null?d[key]:null; if(s==null) s=L10N.en&&L10N.en[key]!=null?L10N.en[key]:key; /* a key with a prefix ("pad:Undo") has its English in the en column */ return args.length?s.replace(/\{(\d)\}/g,(m,i)=>args[+i]!=null?args[+i]:m):s; }
/* how many forms a count word has (v401, H: "Ergaenze russisch als sprache"): English and the five languages of v253 get by
   with two — one and many —, Russian needs three: 1 карточка, 2–4 карточки, 5–20 карточек, chosen by the last digit with
   the teens as the exception (11 карточек, 21 карточка, 111 карточек, 121 карточка); an amount with a decimal point takes
   the middle form, which is the genitive singular Russian wants there (1.5 л → 1.5 литра), and latinUnitMeaning reads such
   amounts off a bottle. A language without an entry here keeps the two forms, so nothing changed for the six of v253. */
const PLURAL={ru:n=>{ if(n!==Math.trunc(n)) return 1; const m=n%10,h=n%100; return (m===1&&h!==11)?0:(m>=2&&m<=4&&(h<12||h>14))?1:2; }};
const pForm=n=>PLURAL[LANG]?PLURAL[LANG](n):(n===1?0:1);
/* the word for a count, without the number: form 0 is the singular key, form 1 the plural key, form 2 the plural key with
   "#many" — the third form lives only in a column whose language names a rule above, the others never look it up. "#few" is
   tried first on form 1 and one single word needs it: LATIN_UNITS["%"], whose English singular and plural are the same word,
   so the plural key alone could not tell 1 процент from 2 процента. A missing form falls back to the plural key, a missing
   word to English, as any missing key does. Shared with latinUnitMeaning, so the app has one plural rule and not two. */
function wordOf(n,w,pl){ const d=L10N[LANG], pk=pl||w+"s", f=pForm(n);
  for(const k of (f===0?[w]:f===1?[pk+"#few",pk]:[pk+"#many",pk])) if(d&&d[k]!=null) return d[k];
  return t(f===0?w:pk); }
/* a count with its word: nOf(3,"card") → "3 cards" / "3 Karten" / "カード3枚" / "3 карточки"; pl = an irregular plural key */
function nOf(n,w,pl){ n=n||0; const tr=wordOf(n,w,pl); return tr.includes("{0}")?tr.replace("{0}",n):`${n} ${tr}`; }
